text:
{
  "requirements": [
    {
      "id": "r1",
      "label": "Web-based inventory dashboard",
      "rfpQuote": "A web-based dashboard showing real-time inventory levels across all 6 warehouses.",
      "section": "§2"
    },
    {
      "id": "r2",
      "label": "Automated low-stock alerts",
      "rfpQuote": "Automated low-stock alerts sent to warehouse managers when items fall below a configurable threshold.",
      "section": "§2"
    },
    {
      "id": "r3",
      "label": "PostgreSQL database integration",
      "rfpQuote": "Integration with our existing PostgreSQL inventory database",
      "section": "§2"
    },
    {
      "id": "r4",
      "label": "Role-based access control",
      "rfpQuote": "Role-based access — warehouse managers should only see their own site; HQ staff should see all sites.",
      "section": "§2"
    },
    {
      "id": "r5",
      "label": "Data migration and onboarding plan",
      "rfpQuote": "A data migration / onboarding plan for rolling this out across all 6 sites with minimal disruption.",
      "section": "§2"
    },
    {
      "id": "r6",
      "label": "Support and maintenance terms",
      "rfpQuote": "Support & maintenance terms after go-live (response times, SLAs).",
      "section": "§2"
    },
    {
      "id": "r7",
      "label": "Documentation of risks and assumptions",
      "rfpQuote": "Clear documentation of any assumptions, limitations, or risks, since inventory decisions will be made based on this system.",
      "section": "§2"
    },
    {
      "id": "r8",
      "label": "Total project budget",
      "rfpQuote": "€80,000–€120,000 total, including first year of support.",
      "section": "§3"
    },
    {
      "id": "r9",
      "label": "Pilot delivery timeline",
      "rfpQuote": "Working pilot at one warehouse within 3 months;",
      "section": "§4"
    },
    {
      "id": "r10",
      "label": "Full rollout timeline",
      "rfpQuote": "full rollout to all 6 sites within 6 months.",
      "section": "§4"
    }
  ],
  "constraints": [
    {
      "id": "c1",
      "kind": "TECHNOLOGY",
      "label": "No database migration",
      "rfpQuote": "no migration to a new database.",
      "section": "§2"
    },
    {
      "id": "c2",
      "kind": "BUDGET",
      "label": "Budget ceiling",
      "rfpQuote": "€80,000–€120,000 total, including first year of support.",
      "section": "§3"
    },
    {
      "id": "c3",
      "kind": "DEADLINE",
      "label": "Pilot delivery deadline",
      "rfpQuote": "Working pilot at one warehouse within 3 months;",
      "section": "§4"
    },
    {
      "id": "c4",
      "kind": "DEADLINE",
      "label": "Full rollout deadline",
      "rfpQuote": "full rollout to all 6 sites within 6 months.",
      "section": "§4"
    }
  ],
  "suggestedWeights": [
    {
      "criterionId": "problem_understanding",
      "weight": 1.2,
      "reason": "The RFP notes challenges with split tracking across spreadsheets and legacy systems that obscure cross-site visibility."
    },
    {
      "criterionId": "scope_clarity",
      "weight": 1.3,
      "reason": "Clear delineations of access roles and rollout deliverables across six distinct sites are explicitly demanded."
    },
    {
      "criterionId": "pricing_clarity",
      "weight": 1.2,
      "reason": "The client specifies a clear budget range that must explicitly include the first year of support."
    },
    {
      "criterionId": "timeline_clarity",
      "weight": 1.3,
      "reason": "Strict phased delivery deadlines are specified for both a 3-month pilot and a 6-month full rollout."
    },
    {
      "criterionId": "tone_persuasiveness",
      "weight": 0.8,
      "reason": "The requirements emphasize operational viability and technical adherence over marketing or sales-focused persuasion."
    },
    {
      "criterionId": "risk_transparency",
      "weight": 1.4,
      "reason": "The client explicitly demands clear documentation of assumptions, limitations, and risks because critical inventory decisions depend on this system."
    },
    {
      "criterionId": "completeness",
      "weight": 1.2,
      "reason": "The client lists multiple operational and support components, including SLAs and onboarding plans, that must all be delivered."
    }
  ]
}
